-- Уменьшенные вдвое обложки (256×256) для карточек «Рандомной игры» в боте.
alter table public.games add column if not exists thumb_img text check (thumb_img is null or char_length(thumb_img) <= 60000);
update public.games set thumb_img = 'data:image/jpeg;base64,' where id = 'stickfight';
update public.games set thumb_img = 'data:image/jpeg;base64,' where id = 'gravity';
update public.games set thumb_img = 'data:image/jpeg;base64,' where id = 'unik';
update public.games set thumb_img = 'data:image/jpeg;base64,' where id = 'metro';
